/// <summary>
/// Validate write.
/// </summary>
/// <returns>True or false.</returns>
public boolean validateWrite()
{
    boolean ret = super();

    ret = ret && this.checkConditionValue();

    return ret;
}

/// <summary>
/// Get the related pricing attribute.
/// </summary>
/// <returns>The pricing attribute.</returns>
public UPSIPricingAttribute pricingAttribute()
{
    UPSPricingAttributeLink link = this.priceAttributeLink();

    return UPSPricingAttributeRepository::priceAttribute(
        link.PriceAttributeClassId,
        link.AttributeProviderClassId,
        link.AttributeName, 
        link.TypeName);
}

internal UPSPricingAttributeLink priceAttributeLink()
{
    UPSPricingAttributeLink link;

    select firstonly link where link.RecId == this.ConditionAttribute;

    return link;
}

/// <summary>
/// Validate condition value
/// </summary>
/// <returns>True if condition value is correct; Otherwise false</returns>
internal boolean checkConditionValue()
{
    boolean ret = true;

    if (this.ConditionValue)
    {
        UPSPricingAttributeLink pricingAttributeLink = this.priceAttributeLink();

        if (pricingAttributeLink.PriceAttributeClassId == classNum(UPSPricingAttributeEcoResAttribute))
        {
            EcoResAttributeDefaultValueHelper attributeDefaultValueHelper = new EcoResAttributeDefaultValueHelper(EcoResAttributeType::findByName(pricingAttributeLink.TypeName));
            AttributeDataType attributeDataType = this.pricingAttribute().getDataType();

            if (attributeDataType != AttributeDataType::TrueFalse
                && attributeDataType != AttributeDataType::Reference
                && !attributeDefaultValueHelper.validateDefaultValue(UPSPricingAttributeLink::getEcoResValue(attributeDataType, this.ConditionValue)))
            {
                ret = checkFailed(strFmt("@UnifiedPricingService:UPSAttributeValueRangeError", this.ConditionValue, pricingAttributeLink.TypeName));
            }
        }
    }

    return ret;
}

static UPSPricingRuleCondition find(RefRecId    _ruleId,
                                    UPSRefRecId _conditionAttribute,
                                    boolean     _update = false)
{
    UPSPricingRuleCondition upsPricingRuleCondition;

    if (_ruleId && _conditionAttribute)
    {
        if (_update)
        {
            upsPricingRuleCondition.selectForUpdate(_update);
        }

        select firstonly upsPricingRuleCondition
            index hint RuleIdx
                where upsPricingRuleCondition.RuleId == _ruleId
                &&    upsPricingRuleCondition.ConditionAttribute == _conditionAttribute;

    }

    return upsPricingRuleCondition;
}
